program2='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sources = [[] for _ in range(w)]
    for r, row in enumerate(grid):
        for color in set(row) - {0}:
            positions = [c for c, value in enumerate(row) if value == color]
            for c in range(min(positions), max(positions) + 1):
                if row[c] == 0:
                    out[r][c] = color
                    sources[c].append((r, color))
    for c, column_sources in enumerate(sources):
        previous = -1
        for r, color in sorted(column_sources):
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r
        # Extend each existing vertical marker upward to the closest horizontal bar.
        r = 0
        while r < h:
            if grid[r][c] == 0:
                r += 1
                continue
            start = r
            while r + 1 < h and grid[r + 1][c] == grid[start][c]:
                r += 1
            color = grid[start][c]
            prior_bars = [sr for sr, _ in column_sources if sr < start]
            if prior_bars:
                top = max(prior_bars) + 1
                for rr in range(top, start):
                    if grid[rr][c] == 0:
                        out[rr][c] = color
            r += 1
    return out
